function crearCuenta(inicial) {
  let saldo = inicial;

  return {
    ingresar(cantidad) {
      saldo += cantidad;
      return saldo;
    },
    retirar(cantidad) {
      saldo -= cantidad;
      return saldo;
    },
    leer() {
      return saldo;
    },
  };
}

function crearImpuesto(porcentaje) {
  return function calcular(base) {
    return base * porcentaje;
  };
}

const iva = crearImpuesto(0.21);
iva(100); // 21
iva(50);  // 10.5

function crearSesion(usuario) {
  let activa = true;

  return {
    cerrar() {
      activa = false;
    },
    estado() {
      return { usuario, activa };
    },
  };
}

function crearRegistrador(escribir) {
  return function registrar(mensaje) {
    escribir(`[app] ${mensaje}`);
  };
}
